    this._checkRange(l, r);
    return l === r ? 0 : this._sum(1, 0, this._length, l, r);
  }

  max(l, r) {
    this._checkRange(l, r);
    return l === r ? -Infinity : this._max(1, 0, this._length, l, r);
  }

